// Root-owned standalone capture; no native production class is replaced.
def prep = new File('/drive-testcomp/opentaint-go-rules/canonical-relations-directional-inside-20261105/analysis-tools/concrete-demand-guidance-design-20261106/storage-validation/saved-normal-replay-capture-20261106')
def pins = new groovy.json.JsonSlurper().parse(new File(prep, 'input-seals.json'))
def runtime = new groovy.json.JsonSlurper().parse(new File(prep, 'runtime-pins.json'))
def sha = { File f -> java.security.MessageDigest.getInstance('SHA-256').digest(f.bytes).encodeHex().toString() }
def verifyInputs = {
    pins.files.each { pin ->
        if (sha(new File(pin.path)) != pin.sha256) throw new GradleException('Capture input changed: ' + pin.path)
    }
    pins.trees.each { pin ->
        def base = new File(pin.path)
        def files = []
        base.eachFileRecurse(groovy.io.FileType.FILES) { files.add(it) }
        files.sort { a, b -> base.toPath().relativize(a.toPath()).toString() <=> base.toPath().relativize(b.toPath()).toString() }
        def digest = java.security.MessageDigest.getInstance('SHA-256')
        files.each { file -> digest.update((base.toPath().relativize(file.toPath()).toString() + '\u0000' + sha(file) + '\n').getBytes('UTF-8')) }
        if (files.size() != pin.files || digest.digest().encodeHex().toString() != pin.sha256)
            throw new GradleException('Capture source tree changed: ' + pin.path)
    }
    runtime.jars.each { pin ->
        if (sha(new File(pin.path)) != pin.sha256) throw new GradleException('Runtime/provider byte pin changed: ' + pin.path)
    }
}
allprojects { p ->
    if (p.projectDir.canonicalFile == new File('/drive-testcomp/opentaint-go-rules/opentaint-w3/core/opentaint-dataflow-core/opentaint-dataflow').canonicalFile) {
        p.afterEvaluate {
            def probe = p.sourceSets.create('savedNormalReplayCapture')
            probe.java.setSrcDirs([])
            probe.resources.setSrcDirs([])
            def kotlinSource = p.kotlin.sourceSets.getByName('savedNormalReplayCapture').kotlin
            kotlinSource.setSrcDirs([new File(prep, 'src')])
            kotlinSource.include('SavedNormalReplaySnapshotProbe.kt', 'SavedNormalReplayFrozenCapture.kt')
            probe.compileClasspath = p.sourceSets.main.output + p.sourceSets.test.output + p.configurations.testCompileClasspath
            def classes = new File(prep, 'execution/compiled')
            probe.output.classesDirs.setFrom(classes)
            probe.output.resourcesDir = new File(prep, 'execution/resources')
            p.tasks.named('compileSavedNormalReplayCaptureKotlin') {
                dependsOn p.tasks.named('testClasses')
                destinationDirectory.set(classes)
                compilerOptions.jvmTarget.set(p.tasks.named('compileKotlin').get().compilerOptions.jvmTarget)
                compilerOptions.freeCompilerArgs.add('-Xfriend-paths=' + [
                    p.layout.buildDirectory.dir('classes/kotlin/main').get().asFile,
                    p.layout.buildDirectory.dir('classes/kotlin/test').get().asFile
                ].collect { it.absolutePath }.join(','))
                doFirst { verifyInputs() }
            }
            p.tasks.register('runSavedNormalReplayFrozenCapture', JavaExec) {
                dependsOn p.tasks.named('compileSavedNormalReplayCaptureKotlin')
                classpath = probe.output + p.sourceSets.test.runtimeClasspath
                mainClass.set('org.opentaint.dataflow.bidi.SavedNormalReplaySnapshotProbe')
                jvmArgs '-Xmx1g', '-XX:ActiveProcessorCount=1'
                timeout.set(java.time.Duration.ofSeconds(20))
                doFirst {
                    verifyInputs()
                    def actual = classpath.files.collect { it.canonicalPath }
                    if (actual != runtime.orderedClasspath) throw new GradleException('Unexpected capture runtime classpath')
                    def allowed = ['org/opentaint/dataflow/bidi/SavedNormalReplayFrozenCapture',
                        'org/opentaint/dataflow/bidi/SavedNormalReplaySnapshotProbe']
                    def hashes = [:]
                    classes.eachFileRecurse(groovy.io.FileType.FILES) { file ->
                        def relative = classes.toPath().relativize(file.toPath()).toString()
                        if (relative.endsWith('.class') && !allowed.any { relative == it + '.class' || relative.startsWith(it + '$') })
                            throw new GradleException('Native overlay or unrelated class in capture: ' + relative)
                        hashes[relative] = sha(file)
                    }
                    new File(prep, 'execution/actual-classpath.txt').text = actual.join('\n') + '\n'
                    new File(prep, 'execution/compiled-class-hashes.json').text = groovy.json.JsonOutput.prettyPrint(groovy.json.JsonOutput.toJson(hashes)) + '\n'
                }
            }
        }
    }
}

